import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import axios from 'axios';
import toast from 'react-hot-toast';
import './UserDashboard.css';

const UserDashboard = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [leads, setLeads] = useState([]);
  const [savedLeads, setSavedLeads] = useState([]);
  const [loading, setLoading] = useState(true);
  const [scraping, setScraping] = useState(false);
  const [scraperResults, setScraperResults] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isDarkMode, setIsDarkMode] = useState(true);

  const [scraperData, setScraperData] = useState({
    city: 'Lahore',
    country: 'Pakistan',
    businessType: 'IT Company',
    maxResults: 10
  });

  const { user, logout, token } = useAuth();
  const navigate = useNavigate();

  const [stats, setStats] = useState({
    totalLeads: 0,
    savedLeads: 0,
    cities: 0,
    emails: 0
  });

  useEffect(() => {
    fetchLeads();
  }, []);

  // FIXED: Removed /api from URL
  const fetchLeads = async () => {
    try {
      const response = await axios.get('/leads', {
        headers: { Authorization: `Bearer ${token}` }
      });
      const data = response.data.data || [];
      setLeads(data);

      const saved = data.filter(l => l.isSaved);
      const cities = [...new Set(data.map(l => l.city).filter(Boolean))];
      const emails = data.filter(l => l.email).length;

      setStats({
        totalLeads: data.length,
        savedLeads: saved.length,
        cities: cities.length,
        emails: emails
      });
    } catch (error) {
      toast.error('Failed to load leads');
    } finally {
      setLoading(false);
    }
  };

  const handleScraperChange = (e) => {
    setScraperData({ ...scraperData, [e.target.name]: e.target.value });
  };

  const quickNiche = (niche) => {
    setScraperData({ ...scraperData, businessType: niche });
  };

  // FIXED: Removed /api from URL
  const runScraper = async () => {
    const { city, country, businessType, maxResults } = scraperData;

    if (!city || !businessType) {
      toast.error('City and Business Type are required');
      return;
    }

    setScraping(true);
    setScraperResults([]);
    toast.loading('🌐 Scraping Google Maps...');

    try {
      const response = await axios.post('/scraper/run', {
        city,
        country,
        businessType,
        maxResults: parseInt(maxResults)
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.success) {
        toast.dismiss();
        toast.success(`✅ Found ${response.data.count} leads!`);
        setScraperResults(response.data.leads || []);
        fetchLeads();
        setActiveTab('scraper');
      } else {
        toast.dismiss();
        toast.error(response.data.message || 'Scraper failed');
      }
    } catch (error) {
      toast.dismiss();
      console.error('Scraper Error:', error);
      toast.error(error.response?.data?.message || 'Failed to scrape. Check backend.');
    } finally {
      setScraping(false);
    }
  };

  // FIXED: Removed /api from URL
  const handleSaveLead = async (leadId) => {
    try {
      await axios.put(`/leads/${leadId}/save`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      toast.success('⭐ Lead saved!');
      fetchLeads();
    } catch (error) {
      toast.error('Failed to save');
    }
  };

  const handleUnsaveLead = async (leadId) => {
    try {
      await axios.put(`/leads/${leadId}/unsave`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      toast.success('Lead unsaved');
      fetchLeads();
    } catch (error) {
      toast.error('Failed to unsave');
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/login');
    toast.success('Logged out');
  };

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode);
    document.body.classList.toggle('light-theme');
  };

  const filteredLeads = leads.filter(lead =>
    lead.companyName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lead.industry?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    lead.city?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const exportCSV = () => {
    if (leads.length === 0) {
      toast.error('No leads to export');
      return;
    }

    const headers = ['Company', 'Email', 'Phone', 'Website', 'Industry', 'City', 'Country', 'Rating', 'Status'];
    const rows = leads.map(l => [
      l.companyName || '',
      l.email || '',
      l.phone || '',
      l.website || '',
      l.industry || '',
      l.city || '',
      l.country || '',
      l.rating || '',
      l.status || 'New'
    ]);

    const csv = [headers, ...rows].map(r => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'leads_export.csv';
    a.click();
    toast.success(`📊 Exported ${leads.length} leads!`);
  };

  if (loading) return (
    <div className="loading-container">
      <div className="loader"></div>
      <p>Loading your dashboard...</p>
    </div>
  );

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: 'fa-solid fa-gauge-high' },
    { id: 'scraper', label: 'Lead Scraper', icon: 'fa-solid fa-magnifying-glass-location' },
    { id: 'leads', label: 'My Leads', icon: 'fa-solid fa-users' },
    { id: 'analytics', label: 'Analytics', icon: 'fa-solid fa-chart-line' },
    { id: 'settings', label: 'Settings', icon: 'fa-solid fa-sliders' }
  ];

  return (
    <div className={`user-dashboard ${isDarkMode ? 'dark' : 'light'}`}>
      <aside className="sidebar">
        <div className="sidebar-brand">
          <div className="brand-icon">
            <i className="fa-solid fa-crosshairs"></i>
          </div>
          <div className="brand-text">
            <h2>LeadHunter</h2>
            <span>Pro</span>
          </div>
        </div>

        <nav className="sidebar-nav">
          {navItems.map(item => (
            <button
              key={item.id}
              className={`nav-item ${activeTab === item.id ? 'active' : ''}`}
              onClick={() => setActiveTab(item.id)}
            >
              <i className={item.icon}></i>
              <span>{item.label}</span>
              {item.id === 'leads' && (
                <span className="badge">{savedLeads.length}</span>
              )}
            </button>
          ))}
        </nav>

        <div className="sidebar-footer">
          <div className="user-info">
            <div className="avatar">
              {user?.name?.charAt(0) || 'U'}
            </div>
            <div className="user-details">
              <p className="name">{user?.name || 'User'}</p>
              <p className="role">{user?.role || 'User'}</p>
            </div>
          </div>
          <button onClick={handleLogout} className="logout-btn">
            <i className="fa-solid fa-power-off"></i>
          </button>
        </div>
      </aside>

      <main className="main-content">
        <header className="main-header">
          <div className="header-left">
            <h1>{navItems.find(item => item.id === activeTab)?.label || 'Dashboard'}</h1>
            <p className="subtitle">
              {activeTab === 'dashboard' && `Welcome back, ${user?.name}!`}
              {activeTab === 'scraper' && '🌍 Find business leads from any country on Google Maps'}
              {activeTab === 'leads' && `📋 You have ${savedLeads.length} saved leads`}
              {activeTab === 'analytics' && '📊 Your lead generation insights'}
              {activeTab === 'settings' && '⚙️ Manage your account settings'}
            </p>
          </div>
          <div className="header-right">
            <button onClick={toggleTheme} className="theme-btn">
              <i className={`fa-solid ${isDarkMode ? 'fa-moon' : 'fa-sun'}`}></i>
            </button>
            {activeTab === 'leads' && leads.length > 0 && (
              <button onClick={exportCSV} className="export-btn">
                <i className="fa-solid fa-file-export"></i> Export
              </button>
            )}
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <div className="tab-content">
            <div className="stats-grid">
              <div className="stat-card purple">
                <div className="stat-icon"><i className="fa-solid fa-users"></i></div>
                <div className="stat-info">
                  <h3>{stats.totalLeads}</h3>
                  <p>Total Leads</p>
                </div>
              </div>
              <div className="stat-card blue">
                <div className="stat-icon"><i className="fa-solid fa-bookmark"></i></div>
                <div className="stat-info">
                  <h3>{stats.savedLeads}</h3>
                  <p>Saved Leads</p>
                </div>
              </div>
              <div className="stat-card cyan">
                <div className="stat-icon"><i className="fa-solid fa-city"></i></div>
                <div className="stat-info">
                  <h3>{stats.cities}</h3>
                  <p>Cities</p>
                </div>
              </div>
              <div className="stat-card yellow">
                <div className="stat-icon"><i className="fa-solid fa-envelope"></i></div>
                <div className="stat-info">
                  <h3>{stats.emails}</h3>
                  <p>Emails Found</p>
                </div>
              </div>
            </div>

            <div className="recent-section">
              <h2>Recent Leads</h2>
              <div className="recent-grid">
                {leads.slice(0, 6).map(lead => (
                  <div key={lead._id} className="recent-card">
                    <h4>{lead.companyName}</h4>
                    <p>{lead.industry || 'N/A'} • {lead.city || 'N/A'}</p>
                    <span className={`status-badge ${lead.status}`}>{lead.status}</span>
                  </div>
                ))}
                {leads.length === 0 && (
                  <p className="empty-state">No leads yet. Run the scraper!</p>
                )}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'scraper' && (
          <div className="tab-content scraper-tab">
            <div className="scraper-container">
              <div className="scraper-config">
                <h3>🌍 Scraper Config</h3>
                <p className="config-subtitle">Enter any city and country to find business leads</p>

                <div className="form-group">
                  <label>City *</label>
                  <input
                    type="text"
                    name="city"
                    value={scraperData.city}
                    onChange={handleScraperChange}
                    placeholder="e.g., Lahore, Dubai, London, New York"
                  />
                </div>

                <div className="form-group">
                  <label>Country</label>
                  <input
                    type="text"
                    name="country"
                    value={scraperData.country}
                    onChange={handleScraperChange}
                    placeholder="e.g., Pakistan, UAE, UK, USA"
                  />
                </div>

                <div className="form-group">
                  <label>Business Type *</label>
                  <input
                    type="text"
                    name="businessType"
                    value={scraperData.businessType}
                    onChange={handleScraperChange}
                    placeholder="e.g., IT Company, Restaurant, Dental Clinic"
                  />
                </div>

                <div className="form-group">
                  <label>Max Results</label>
                  <input
                    type="number"
                    name="maxResults"
                    value={scraperData.maxResults}
                    onChange={handleScraperChange}
                    min="5"
                    max="50"
                  />
                </div>

                <div className="quick-niches">
                  <span>Quick:</span>
                  {['Dental Clinic', 'IT Company', 'Restaurant', 'Law Firm', 'Hotel', 'Hospital'].map(niche => (
                    <button key={niche} onClick={() => quickNiche(niche)} className="niche-btn">
                      {niche}
                    </button>
                  ))}
                </div>

                <button
                  onClick={runScraper}
                  className="scraper-btn"
                  disabled={scraping}
                >
                  {scraping ? (
                    <>
                      <i className="fa-solid fa-spinner fa-spin"></i> Scraping Google Maps...
                    </>
                  ) : (
                    <>
                      <i className="fa-solid fa-play"></i> Run Scraper
                    </>
                  )}
                </button>
              </div>

              <div className="scraper-results">
                <div className="results-header">
                  <h3>Live Results</h3>
                  <span className="result-count">{scraperResults.length} found</span>
                </div>

                <div className="results-list">
                  {scraperResults.length === 0 ? (
                    <div className="empty-results">
                      <i className="fa-solid fa-search"></i>
                      <p>Run the scraper to find leads from Google Maps</p>
                      <p className="hint">🌍 Supports any country worldwide</p>
                    </div>
                  ) : (
                    scraperResults.map((lead, index) => (
                      <div key={index} className="result-item">
                        <div className="result-info">
                          <h4>
                            {lead.companyName || 'Unknown'}
                            {lead.rating && <span className="rating">⭐ {lead.rating}</span>}
                          </h4>
                          <p>
                            {lead.industry || 'N/A'} • {lead.city || 'N/A'}
                            {lead.country && `, ${lead.country}`}
                          </p>
                          {lead.address && <p className="contact"><i className="fa-solid fa-location-dot"></i> {lead.address}</p>}
                          {lead.phone && <p className="contact"><i className="fa-solid fa-phone"></i> {lead.phone}</p>}
                          {lead.website && (
                            <p className="contact">
                              <i className="fa-solid fa-globe"></i> 
                              <a href={lead.website} target="_blank" rel="noopener noreferrer">{lead.website}</a>
                            </p>
                          )}
                        </div>
                        <button
                          onClick={() => handleSaveLead(lead._id)}
                          className="save-btn"
                        >
                          <i className="fa-regular fa-bookmark"></i> Save
                        </button>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'leads' && (
          <div className="tab-content leads-tab">
            <div className="leads-header">
              <div className="leads-search">
                <i className="fa-solid fa-search"></i>
                <input
                  type="text"
                  placeholder="Search leads by name, industry, or city..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
              <span className="leads-count">{savedLeads.length} Saved Leads</span>
            </div>

            <div className="leads-grid">
              {filteredLeads.length === 0 ? (
                <div className="empty-state">
                  <i className="fa-solid fa-inbox"></i>
                  <p>No leads found</p>
                  <button onClick={() => setActiveTab('scraper')} className="primary-btn">
                    Go to Scraper
                  </button>
                </div>
              ) : (
                filteredLeads.map(lead => (
                  <div key={lead._id} className="lead-card">
                    <div className="lead-card-header">
                      <h3>
                        {lead.companyName}
                        {lead.rating && <span className="rating-badge">⭐ {lead.rating}</span>}
                      </h3>
                      <span className={`status-badge ${lead.status}`}>{lead.status}</span>
                    </div>

                    <div className="lead-card-body">
                      {lead.industry && (
                        <p><i className="fa-solid fa-tag"></i> {lead.industry}</p>
                      )}
                      {lead.address && (
                        <p><i className="fa-solid fa-location-dot"></i> {lead.address}</p>
                      )}
                      {lead.city && (
                        <p><i className="fa-solid fa-city"></i> {lead.city}{lead.country ? `, ${lead.country}` : ''}</p>
                      )}
                      {lead.phone && (
                        <p><i className="fa-solid fa-phone"></i> {lead.phone}</p>
                      )}
                      {lead.email && (
                        <p><i className="fa-solid fa-envelope"></i> {lead.email}</p>
                      )}
                      {lead.website && (
                        <p><i className="fa-solid fa-globe"></i> <a href={lead.website} target="_blank" rel="noopener noreferrer">{lead.website}</a></p>
                      )}
                    </div>

                    <div className="lead-card-actions">
                      {lead.isSaved ? (
                        <button onClick={() => handleUnsaveLead(lead._id)} className="unsave-btn">
                          <i className="fa-solid fa-bookmark"></i> Saved
                        </button>
                      ) : (
                        <button onClick={() => handleSaveLead(lead._id)} className="save-btn">
                          <i className="fa-regular fa-bookmark"></i> Save
                        </button>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {activeTab === 'analytics' && (
          <div className="tab-content analytics-tab">
            <h2>📊 Analytics</h2>
            <div className="analytics-grid">
              <div className="analytics-card">
                <h3>Leads by Country</h3>
                <div className="chart-container">
                  {[...new Set(leads.map(l => l.country).filter(Boolean))].map(country => {
                    const count = leads.filter(l => l.country === country).length;
                    const max = leads.length || 1;
                    const pct = Math.round((count / max) * 100);
                    return (
                      <div key={country} className="chart-bar">
                        <span>{country}</span>
                        <div className="bar-track">
                          <div className="bar-fill" style={{ width: `${Math.max(pct, 10)}%` }}>
                            <span className="bar-label">{count}</span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                  {leads.length === 0 && <p className="empty-state">No data yet</p>}
                </div>
              </div>

              <div className="analytics-card">
                <h3>Leads by Industry</h3>
                <div className="chart-container">
                  {[...new Set(leads.map(l => l.industry).filter(Boolean))].map(industry => {
                    const count = leads.filter(l => l.industry === industry).length;
                    const max = leads.length || 1;
                    const pct = Math.round((count / max) * 100);
                    return (
                      <div key={industry} className="chart-bar">
                        <span>{industry}</span>
                        <div className="bar-track">
                          <div className="bar-fill" style={{ width: `${Math.max(pct, 10)}%` }}>
                            <span className="bar-label">{count}</span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                  {leads.length === 0 && <p className="empty-state">No data yet</p>}
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="tab-content settings-tab">
            <div className="settings-card">
              <h2>⚙️ Account Settings</h2>

              <div className="settings-section">
                <h3>Profile</h3>
                <div className="settings-field">
                  <label>Name</label>
                  <input type="text" value={user?.name || ''} disabled />
                </div>
                <div className="settings-field">
                  <label>Email</label>
                  <input type="email" value={user?.email || ''} disabled />
                </div>
                <div className="settings-field">
                  <label>Role</label>
                  <input type="text" value={user?.role || 'User'} disabled />
                </div>
              </div>

              <div className="settings-section">
                <h3>Change Password</h3>
                <div className="settings-field">
                  <label>Current Password</label>
                  <input type="password" placeholder="Enter current password" />
                </div>
                <div className="settings-field">
                  <label>New Password</label>
                  <input type="password" placeholder="Enter new password" />
                </div>
                <div className="settings-field">
                  <label>Confirm Password</label>
                  <input type="password" placeholder="Confirm new password" />
                </div>
                <button className="primary-btn">Update Password</button>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default UserDashboard;
